Preface



                  Video Loading 



Allow a few seconds for youtube video previews to load on this page


This guide is a modification of Unity’s official Beginner Scripting tutorial series. In combines all of the lessons into one page and fixes minor bugs so that all of the code examples work in Unity 6. Some lessons have been substituted.
Before beginning, make sure to configure your default script editor

Scripts as Behavior Components



                  Script differs from video 



The script for this lesson has been modified to work with the new Unity Input System.



ExampleBehaviourScript.cs
using UnityEngine;  
using System.Collections;  
using UnityEngine.InputSystem;  

public class ExampleBehaviourScript : MonoBehaviour  
{  
	void Update()  
	{  
		if (Keyboard.current.rKey.wasPressedThisFrame)  
		{  
			GetComponent&lt;Renderer&gt; ().material.color = Color.red;  
		}  
		if (Keyboard.current.gKey.wasPressedThisFrame)  
		{  
			GetComponent&lt;Renderer&gt;().material.color = Color.green;  
		}  
		if (Keyboard.current.bKey.wasPressedThisFrame)  
		{  
			GetComponent&lt;Renderer&gt;().material.color = Color.blue;  
		}  
	}  
}

Variables and Functions

VariablesAndFunctions.cs
using UnityEngine;
using System.Collections;

public class VariablesAndFunctions : MonoBehaviour
{   
    int myInt = 5;


    void Start ()
    {
        myInt = MultiplyByTwo(myInt);
        Debug.Log (myInt);
    }


    int MultiplyByTwo (int number)
    {
        int result;
        result = number * 2;
        return result;
    }
}

Conventions and Syntax

BasicSyntax.cs
using UnityEngine;
using System.Collections;

public class BasicSyntax : MonoBehaviour
{
    void Start ()
    {
        //this line is there to tell me the x position of my object

        /*Hi there!
         * this is two lines!
         * */
        Debug.Log(transform.position.x);

